import{_ as l,a0 as p,w as r,s as o,ao as d,I as n,x as t,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"刪除 Git 遠程分支的本地引用 | LCTT x X-CMD","titleTemplate":false,"description":"刪除 Git 遠程分支的本地引用 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"刪除 Git 遠程分支的本地引用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"刪除 Git 遠程分支的本地引用 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220805 Delete the local reference to a remote branch in Git","title":"刪除 Git 遠程分支的本地引用","tag":"202208","desc":""},"relativePath":"202208/20220805 Delete the local reference to a remote branch in Git.md","filePath":"[post].md"}'),g={name:"202208/20220805 Delete the local reference to a remote branch in Git.md"};function h(c,e,u,b,k,m){const s=p("Link");return r(),o("div",null,[e[15]||(e[15]=d(`<h1 id="刪除-git-遠程分支的本地引用" tabindex="-1">刪除 Git 遠程分支的本地引用 <a class="header-anchor" href="#刪除-git-遠程分支的本地引用" aria-label="Permalink to “刪除 Git 遠程分支的本地引用”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/11/150612dv5diwgve5k2cobk.jpg" alt=""></p><blockquote><p>遵循幾個簡單的步驟來保持 Git 倉庫的整潔</p></blockquote><p>在合併一個 GibLab 的合併請求（MR）或 GitHub 的拉取請求（PR）後，你通常需要從遠程倉庫中刪掉這個主題分支來保持倉庫的整潔。然而，這隻會刪掉遠程倉庫的主題分支。本地 Git 倉庫也會從例行清理中收益。</p><p>要同步本地倉庫和遠程倉庫的信息，可以執行 <code>git prune</code> 命令來刪除本地倉庫中遠程分支的本地引用。</p><p>按照以下三個簡單的步驟：</p><p>1、檢出倉庫中的核心分支（比如 <code>main</code> 或者 <code>master</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout &lt;central_branch_name&gt;</span></span></code></pre></div><p>2、列出所有遠程和本地分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git branch -a</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>4.10.z</span></span>
<span class="line"><span>* master</span></span>
<span class="line"><span>  remotes/mydata/4.9-stage</span></span>
<span class="line"><span>  remotes/mydata/4.9.z</span></span>
<span class="line"><span>  remotes/mydata/test-branch</span></span></code></pre></div><p>在這個例子中，<code>test-branch</code> 是從遠程倉庫中刪除的主題分支的名字。</p><p>3、刪除遠程分支的本地引用：</p><p>首先，列出所有可以從本地倉庫中刪除的分支：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote prune origin --dry-run</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Pruning origin</span></span>
<span class="line"><span>URL: git@example.com:myorg/mydata-4.10.git</span></span>
<span class="line"><span>* [would prune] origin/test-branch</span></span></code></pre></div><p>然後，刪除遠程分支的本地引用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git remote prune origin</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Pruning origin</span></span>
<span class="line"><span>URL: git@example.com:myorg/mydata-4.10.git</span></span>
<span class="line"><span>* [pruned] origin/test-branch</span></span></code></pre></div><p>就是這樣！</p><h3 id="維護-git-倉庫" tabindex="-1">維護 Git 倉庫 <a class="header-anchor" href="#維護-git-倉庫" aria-label="Permalink to “維護 Git 倉庫”">​</a></h3><p>保持 Git 倉庫的整潔，一開始似乎並不緊急，但是隨着倉庫規模的增長，刪除不必要的數據就變得更為重要。不要讓從無用的數據篩選而拖慢你。</p><p>經常刪除遠程分支的本地引用，是維護一個可用的 Git 倉庫是一個好方法。</p><hr>`,27)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),i(s,{href:"https://opensource.com/article/22/8/delete-local-reference-remote-branch-git"},{default:a(()=>[...e[0]||(e[0]=[t("https://opensource.com/article/22/8/delete-local-reference-remote-branch-git",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=t("作者：",-1)),i(s,{href:"https://opensource.com/users/agantony"},{default:a(()=>[...e[2]||(e[2]=[t("Agil Antony",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),i(s,{href:"https://github.com/lkxed"},{default:a(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),i(s,{href:"https://github.com/Yufei-Yan"},{default:a(()=>[...e[4]||(e[4]=[t("Yufei-Yan",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const x=l(g,[["render",h]]);export{C as __pageData,x as default};
